1	// Main game logic hook for Jelly Volleyball
2	
3	import { useState, useEffect, useCallback, useRef } from 'react';
4	import type { GameState, GameConfig, Controls } from '../components/Games/JellyVolleyball/types';
5	import {
6	  updatePlayer,
7	  updateBall,
8	  handleBallPlayerCollision,
9	  defaultPhysicsConfig,
10	} from '../components/Games/JellyVolleyball/physics';
11	import { calculateAIControls, defaultAIConfig } from '../components/Games/JellyVolleyball/ai';
12	
13	const DEFAULT_CONFIG: GameConfig = {
14	  courtWidth: 800,
15	  courtHeight: 400,
16	  netHeight: 100, // 1/4 of courtHeight (400 / 4 = 100)
17	  playerRadius: 35,
18	  ballRadius: 32, // Big ball - almost as big as the jelly players!
19	  gravity: 0.06, // Even lower gravity - ball floats much longer
20	  pointsToWin: 7,
21	};
22	
23	// Initialize game state
24	function createInitialState(config: GameConfig): GameState {
25	  const player1StartX = config.courtWidth / 4;
26	  const player2StartX = (config.courtWidth * 3) / 4;
27	  const startY = config.courtHeight - config.playerRadius;
28	
29	  return {
30	    player1: {
31	      position: { x: player1StartX, y: startY },
32	      velocity: { x: 0, y: 0 },
33	      radius: config.playerRadius,
34	      mass: 1.0,
35	      wobbleOffset: { x: 0, y: 0 },
36	      wobbleVelocity: { x: 0, y: 0 },
37	      color: '#FF6B6B',
38	      isAI: false,
39	    },
40	    player2: {
41	      position: { x: player2StartX, y: startY },
42	      velocity: { x: 0, y: 0 },
43	      radius: config.playerRadius,
44	      mass: 1.0,
45	      wobbleOffset: { x: 0, y: 0 },
46	      wobbleVelocity: { x: 0, y: 0 },
47	      color: '#4ECDC4',
48	      isAI: true,
49	    },
50	    ball: {
