    img.src = dataURL;
    if (!img.complete) return dataURL;
    const canvas = document.createElement('canvas');
    canvas.width = img.width || 800;
    canvas.height = img.height || 600;
    const ctx = canvas.getContext('2d');
    if (!ctx) return dataURL;
    ctx.drawImage(img, 0, 0);
