    }

    drawingsRef.current = next;
    setDrawings(next);
    return newDrawing;
  }, []);

  const remove = useCallback((id: string) => {
    const next = drawingsRef.current.filter(d => d.id !== id);
    drawingsRef.current = next;
    setDrawings(next);
    storage.set(STORAGE_KEY, next);
  }, []);

  const clear = useCallback(() => {
    drawingsRef.current = [];
    setDrawings([]);
    storage.remove(STORAGE_KEY);
  }, []);

  return { drawings, save, remove, clear };
}

import { test, expect } from '@playwright/test';

/**
 * Regression net: clicking every home tile navigates away from home,
 * and clicking "← Home" returns to the home page.
 * Covers all 13 games. Runs in order to catch navigation regressions in later phases.
 */
const GAME_TILES = [
  'Color Blocks',
  'Sudoku',
  'Tetris',
  'Jelly Volleyball',
  'Snake',
  'Memory Match',
  'Drawing Challenge',
  'Pop Balloons',
  'Simon Says',
  'Bubble Pop',
  'Color Mixer',
  'Math Facts',
  'Shape Sorting',
];

/**
 * Regression test: JellyVolleyball canvas must fit within a 360px viewport
 * (verifies the touch-coord fix — canvas no longer overflows, so CSS scaling
 * stays ≤1× and raw clientX maps correctly to in-game coords).
 */
test('JellyVolleyball canvas fits within 360px viewport and handles interaction', async ({ page }) => {
  await page.setViewportSize({ width: 360, height: 800 });
  await page.goto('/');

  await page.getByRole('button', { name: /jelly volleyball/i }).click();
  await expect(page.getByRole('heading', { name: /Fun Games to Play/i })).not.toBeVisible();

  const canvas = page.locator('canvas').first();
  await expect(canvas).toBeVisible();

  // Canvas must not overflow the 360px viewport (key invariant for correct touch coords)
  const box = await canvas.boundingBox();
  expect(box!.width).toBeLessThanOrEqual(361); // +1 for subpixel rounding

  // Click the left quarter of the canvas — exercises the mouse/touch handler
  // without requiring canvas pixel inspection
  await canvas.click({ position: { x: Math.floor(box!.width * 0.25), y: Math.floor(box!.height * 0.75) } });

  // Game still rendering after interaction (no crash from bad coords)
  await expect(canvas).toBeVisible();

  // Return home
  await page.getByRole('button', { name: /home/i }).click();
  await expect(page.getByRole('heading', { name: /Fun Games to Play/i })).toBeVisible();
});

test('click every home tile, assert navigation, return home', async ({ page }) => {
  await page.goto('/');

  // Unique heading only present on the home page
  const homeHeading = page.getByRole('heading', { name: /Fun Games to Play/i });
  await expect(homeHeading).toBeVisible();

  for (const tileName of GAME_TILES) {
    // Click the game tile on the home page
    await page.getByRole('button', { name: new RegExp(tileName, 'i') }).click();

    // Assert we navigated away (home heading no longer visible)
    await expect(homeHeading).not.toBeVisible({ timeout: 5000 });

    // Click the back button (← Home) to return home
    await page.getByRole('button', { name: /home/i }).click();

    // Assert we're back on the home page
    await expect(homeHeading).toBeVisible({ timeout: 5000 });
  }
});

import { describe, test, expect, vi, afterEach } from 'vitest';
import { render } from '@testing-library/react';
import BubblePopPage from './BubblePopPage';

// Stub the game hook — we only care about the DOM side-effect (style injection)
vi.mock('../../../hooks/useBubblePop', () => ({
  useBubblePop: () => ({
    gameState: {
      bubbles: [],
      score: 0,
      bubblesPopped: 0,
      gameStatus: 'playing' as const,
    },
    popBubble: vi.fn(),
    togglePause: vi.fn(),
    resetGame: vi.fn(),
  }),
}));

afterEach(() => {
  // Clean up the injected style so tests are isolated.
  document.getElementById('bubble-pop-animations')?.remove();
});

describe('BubblePopPage — style-tag deduplication', () => {
  test('remounting does not inject a second #bubble-pop-animations style tag', () => {
    const { unmount: unmount1 } = render(
      <BubblePopPage onNavigateHome={vi.fn()} />
    );
    unmount1();

    const { unmount: unmount2 } = render(
      <BubblePopPage onNavigateHome={vi.fn()} />
    );

    expect(document.querySelectorAll('#bubble-pop-animations').length).toBe(1);

    unmount2();
  });
});

import { describe, test, expect } from 'vitest';
import { computeGameX } from './useJellyVolleyball';

/**
 * Unit tests for the touch coordinate scaling in JellyVolleyball.
 *
 * The canvas is rendered at its intrinsic size (e.g. 800×400) but CSS scales
 * it down to fit the device viewport (e.g. displayed as 360×180 on a phone).
 * Raw clientX/Y values must be multiplied by the scale factor to land at the
 * correct in-game position.
 */
describe('computeGameX — touch coordinate scaling', () => {
  test('touch at center of 360px display maps to game-center (400) on 800px court', () => {
    // Canvas intrinsic width: 800px
    // Displayed rect width:   360px  (CSS scales 800 → 360 on a phone)
    // Touch at clientX=180   (= center of the 360px display)
    // Expected gameX = 180 × (800 / 360) = 400 (= center of court)
    expect(computeGameX(180, 0, 360, 800)).toBe(400);
  });

  test('after resize to 720px wide, touch at 360 still maps to game-center (400)', () => {
    // Simulates a window.resize event that recomputes the cached rect:
    // New rect.width = 720px, touch at clientX=360 (center of the new size)
    // scaleX = 800 / 720  →  gameX = 360 × (800 / 720) = 400
    expect(computeGameX(360, 0, 720, 800)).toBe(400);
  });
});

// Main page component for Jelly Volleyball game

import { useJellyVolleyball } from '../../../hooks/useJellyVolleyball';
import GameCanvas from './GameCanvas';

interface Props {
  onNavigateHome: () => void;
}

export default function JellyVolleyballPage({ onNavigateHome }: Props) {
  const courtWidth = Math.min(window.innerWidth - 32, 800);
  const courtHeight = courtWidth / 2;
  const { gameState, isPaused, canvasRef, controls } = useJellyVolleyball({
    courtWidth,
    courtHeight,
    netHeight: courtHeight / 4,
    playerRadius: 35,
    ballRadius: 32,
    gravity: 0.06,
    pointsToWin: 7,
  });

  return (
    <div className="p-4 min-h-screen bg-gradient-to-b from-blue-100 to-blue-200">
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <h1 className="text-3xl font-bold text-blue-900">Jelly Volleyball</h1>
        <div className="flex gap-2">
          <button className="kid-button text-sm" onClick={controls.togglePause}>
            {isPaused ? '▶️ Resume' : '⏸️ Pause'}
          </button>
          <button className="kid-button text-sm" onClick={onNavigateHome}>
            ← Home
          </button>
        </div>
      </div>

      {/* Game Canvas */}
      <div className="flex justify-center mb-4">
        <GameCanvas
          ref={canvasRef}
          gameState={gameState}
          width={gameState.court.width}
          height={gameState.court.height}
        />
      </div>

      {/* Controls Info */}
      <div className="kid-card max-w-4xl mx-auto">
        <h2 className="text-xl font-bold mb-3 text-center">How to Play</h2>

        <div className="grid md:grid-cols-2 gap-4">
          {/* Player 1 Controls */}
          <div className="bg-red-100 p-4 rounded-lg border-2 border-red-300">
            <h3 className="font-bold text-lg mb-2 text-red-700">
              🔴 Player 1 (Left - You!)
            </h3>
            <div className="space-y-2 text-sm">
              <div className="flex justify-between">
                <span className="font-semibold">Keyboard:</span>
                <span className="bg-white px-2 py-1 rounded">A/D/← →/W ↑ Space</span>
              </div>
              <div className="flex justify-between">
                <span className="font-semibold">Mouse:</span>
                <span className="bg-white px-2 py-1 rounded">Move + Right-Click to Jump</span>
              </div>
              <div className="flex justify-between">
                <span className="font-semibold">Touch:</span>
                <span className="bg-white px-2 py-1 rounded">Drag + Swipe Up to Jump</span>
              </div>
            </div>

            {/* Touch Controls for Mobile */}
            <div className="mt-3 pt-3 border-t border-red-300">
              <p className="font-semibold mb-2 text-sm">Touch Controls:</p>
              <div className="flex gap-2 justify-center">
                <button
                  className="kid-button text-2xl px-6 py-3"
                  onTouchStart={() => controls.setControl('left', true)}
                  onTouchEnd={() => controls.setControl('left', false)}
                  onMouseDown={() => controls.setControl('left', true)}
                  onMouseUp={() => controls.setControl('left', false)}
                  onMouseLeave={() => controls.setControl('left', false)}
                >
                  ←
                </button>
                <button
                  className="kid-button text-2xl px-6 py-3"
                  onTouchStart={() => controls.setControl('jump', true)}
                  onTouchEnd={() => controls.setControl('jump', false)}
                  onMouseDown={() => controls.setControl('jump', true)}
                  onMouseUp={() => controls.setControl('jump', false)}
                  onMouseLeave={() => controls.setControl('jump', false)}
                >
                  ↑
                </button>
                <button
                  className="kid-button text-2xl px-6 py-3"
                  onTouchStart={() => controls.setControl('right', true)}
                  onTouchEnd={() => controls.setControl('right', false)}
                  onMouseDown={() => controls.setControl('right', true)}
                  onMouseUp={() => controls.setControl('right', false)}
                  onMouseLeave={() => controls.setControl('right', false)}
                >
                  →
                </button>
              </div>
            </div>
          </div>

          {/* Player 2 (AI) Info */}
          <div className="bg-teal-100 p-4 rounded-lg border-2 border-teal-300">
            <h3 className="font-bold text-lg mb-2 text-teal-700">
              🔵 Player 2 (Right - AI)
            </h3>
            <div className="space-y-2 text-sm">
              <p>
                <span className="font-semibold">Controlled by:</span> Computer AI
              </p>
              <p>
                <span className="font-semibold">Difficulty:</span> Medium
              </p>
              <p className="text-xs text-gray-600 mt-2">
                The AI will try to hit the ball back to you. Try to make it land on their side!
              </p>
            </div>
          </div>
        </div>

        {/* Game Rules */}
        <div className="mt-4 p-4 bg-yellow-50 rounded-lg border-2 border-yellow-300">
          <h3 className="font-bold text-lg mb-2 text-yellow-800">📋 Game Rules</h3>
          <ul className="space-y-1 text-sm list-disc list-inside">
            <li>Keep the ball from touching the ground on your side</li>
            <li>Make the ball land on your opponent's side to score</li>
            <li>First player to <strong>{gameState.court.width ? '7' : ''} points</strong> wins!</li>
            <li>The ball must go over the net</li>
            <li>Use your jelly body to bounce the ball</li>
          </ul>
        </div>

        {/* Additional Controls */}
        <div className="mt-4 flex justify-center gap-3">
          <button className="kid-button" onClick={controls.resetGame}>
            🔄 New Game
          </button>
          {isPaused && (
            <div className="text-center py-2 px-4 bg-yellow-100 border-2 border-yellow-400 rounded-lg">
              <span className="font-bold">⏸️ PAUSED</span>
            </div>
          )}
        </div>
      </div>

      {/* Game Status Messages */}
      {gameState.lastScorer && gameState.gameStatus === 'playing' && (
        <div className="fixed top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 pointer-events-none">
          <div className="bg-white border-4 border-blue-500 rounded-lg px-8 py-4 shadow-2xl animate-bounce">
            <p className="text-3xl font-bold text-blue-900">
              {gameState.lastScorer === 1 ? 'You Scored! 🎉' : 'AI Scored! 💪'}
            </p>
          </div>
        </div>
      )}
    </div>
  );
}

