// Flood fill algorithm (bucket fill)
const floodFill = useCallback((startX: number, startY: number, fillColor: string) => {
  const canvas = canvasRef.current;
  const context = contextRef.current;
  if (!canvas || !context) return;

  // Convert display coordinates to internal canvas pixel coordinates
  const devicePixelRatio = window.devicePixelRatio || 1;
  const pixelX = Math.floor(startX * devicePixelRatio);
  const pixelY = Math.floor(startY * devicePixelRatio);

  // Get image data
  const imageData = context.getImageData(0, 0, canvas.width, canvas.height);
  const pixels = imageData.data;

  // Convert fill color to RGB
  const fillRgb = hexToRgb(fillColor);
  if (!fillRgb) return;

  // Get the color at the starting position using scaled coordinates
  const startPos = (pixelY * canvas.width + pixelX) * 4;
  const startR = pixels[startPos];
  const startG = pixels[startPos + 1];
  const startB = pixels[startPos + 2];
  const startA = pixels[startPos + 3];

  // If start color is the same as fill color, no need to fill
  if (startR === fillRgb.r && startG === fillRgb.g && startB === fillRgb.b) {
    return;
  }

  // Flood fill using stack-based approach (more efficient than recursion)
  const stack: Array<[number, number]> = [[pixelX, pixelY]];
  const visited = new Set<string>();

  while (stack.length > 0) {
    const [x, y] = stack.pop()!;

    // Skip if out of bounds
    if (x < 0 || x >= canvas.width || y < 0 || y >= canvas.height) continue;

    // Skip if already visited
    const key = `${x},${y}`;
    if (visited.has(key)) continue;
    visited.add(key);

    const pos = (y * canvas.width + x) * 4;
    const r = pixels[pos];
    const g = pixels[pos + 1];
    const b = pixels[pos + 2];
    const a = pixels[pos + 3];

    // Skip if color doesn't match the start color
    if (r !== startR || g !== startG || b !== startB || a !== startA) continue;

    // Fill the pixel
    pixels[pos] = fillRgb.r;
    pixels[pos + 1] = fillRgb.g;
    pixels[pos + 2] = fillRgb.b;
    pixels[pos + 3] = 255; // Full opacity

    // Add neighboring pixels to stack
    stack.push([x + 1, y]);
    stack.push([x - 1, y]);
    stack.push([x, y + 1]);
    stack.push([x, y - 1]);
  }

  // Put the modified image data back to canvas
  context.putImageData(imageData, 0, 0);

  // Notify parent component of changes
  if (onDrawingChange) {
    onDrawingChange(canvas.toDataURL('image/png'));
  }
}, [onDrawingChange]);

