/**
 * GameLayout Component
 * Shared layout wrapper for all games
 * Provides consistent header, navigation, and styling
 */

import React from 'react';

interface GameLayoutProps {
  title: string;
  emoji: string;
  onNavigateHome: () => void;
  children: React.ReactNode;
  headerActions?: React.ReactNode;
  bgColorClass?: string;
}

const GameLayout: React.FC<GameLayoutProps> = ({
  title,
  emoji,
  onNavigateHome,
  children,
  headerActions,
  bgColorClass = 'bg-gradient-to-b from-blue-100 to-blue-200'
}) => {
  return (
    <div className={`min-h-screen ${bgColorClass} p-2 md:p-4`}>
      {/* Header - Mobile First */}
      <div className="flex items-center justify-between mb-2 md:mb-4 gap-2">
        {/* Title - Compact on mobile */}
        <h1 className="text-xl md:text-3xl font-bold text-gray-800 flex items-center gap-1 md:gap-2">
          <span className="text-2xl md:text-3xl">{emoji}</span>
          <span className="hidden sm:inline">{title}</span>
        </h1>

        {/* Actions and Home Button - Compact on mobile */}
        <div className="flex gap-1 md:gap-2 flex-wrap items-center justify-end">
          {headerActions}

          <button
            className="kid-button text-xs md:text-sm bg-slate-500 hover:bg-slate-600 px-2 md:px-4 py-1 md:py-2"
            onClick={onNavigateHome}
            aria-label="← Home"
          >
            <span className="md:hidden" aria-hidden="true">←</span>
            <span className="hidden md:inline" aria-hidden="true">← Home</span>
          </button>
        </div>
      </div>

      {/* Game Content - Maximum space on mobile */}
      <div className="game-content">
        {children}
      </div>
    </div>
  );
};

export default GameLayout;

import React, { useState } from 'react';
import { useColorBlocksGame } from '../../../hooks/useColorBlocksGame';
import ColorBlocksBoard from './ColorBlocksBoard';
import { GameConfig } from './types';
import GameLayout from '../../shared/GameLayout';

interface ColorBlocksPageProps {
  onNavigateHome: () => void;
}

const ColorBlocksPage: React.FC<ColorBlocksPageProps> = ({ onNavigateHome }) => {
  const [config, setConfig] = useState<GameConfig>({
    gridWidth: 8,
    gridHeight: 10,
    initialColors: 4
  });
  const [showSettings, setShowSettings] = useState(false);
  const [tempConfig, setTempConfig] = useState<GameConfig>(config);

  const { gameState, controls } = useColorBlocksGame(config);

  const handleApplySettings = () => {
    setConfig(tempConfig);
    setShowSettings(false);
    // Reset game will be triggered by config change in useColorBlocksGame
    controls.resetGame();
  };

  return (
    <GameLayout
      title="Color Blocks"
      emoji="🎨"
      onNavigateHome={onNavigateHome}
      bgColorClass="bg-gradient-to-b from-purple-100 to-pink-100"
    >
      {/* Score Display - Compact */}
      <div className="px-3 py-2 bg-white shadow-sm border-b border-gray-200">
        <div className="flex justify-around items-center text-center">
          <div>
            <p className="text-xs font-semibold text-purple-700">Score</p>
            <p className="text-xl font-bold text-purple-900">{gameState.score}</p>
          </div>
          <div>
            <p className="text-xs font-semibold text-pink-700">High Score</p>
            <p className="text-xl font-bold text-pink-900">{gameState.highScore}</p>
          </div>
          <div>
            <p className="text-xs font-semibold text-indigo-700">Moves</p>
            <p className="text-xl font-bold text-indigo-900">{gameState.moves}</p>
          </div>
        </div>
      </div>

      {/* Message Display - Compact */}
      <div className="px-3 py-2 bg-yellow-100 border-b border-yellow-200">
        <p className="text-sm font-semibold text-yellow-900 text-center">{gameState.message}</p>
      </div>

      {/* Game Board - Centered and Prominent */}
      <div className="flex justify-center py-4 px-2">
        <ColorBlocksBoard
          gameState={gameState}
          onBlockClick={controls.handleBlockClick}
          onBlockHover={controls.handleBlockHover}
          onMouseLeave={controls.clearSelection}
        />
      </div>

      {/* Compact Controls */}
      <div className="px-3 pb-3">
        <div className="flex gap-2 justify-center">
          <button
            className="flex-1 max-w-[200px] py-2 px-4 bg-green-500 hover:bg-green-600 active:bg-green-700 text-white font-bold rounded-lg shadow-md"
            onClick={controls.resetGame}
          >
            🔄 New Game
          </button>
          <button
            className="flex-1 max-w-[200px] py-2 px-4 bg-blue-500 hover:bg-blue-600 active:bg-blue-700 text-white font-bold rounded-lg shadow-md"
            onClick={() => {
              setTempConfig(config);
              setShowSettings(!showSettings);
            }}
          >
            ⚙️ Settings
          </button>
        </div>
      </div>

      {/* Settings Panel - Compact */}
      {showSettings && (
        <div className="mx-3 mb-4 bg-white rounded-lg shadow-md p-4">
          <h2 className="text-xl font-bold text-blue-800 mb-3">⚙️ Settings</h2>

          <div className="space-y-4">
            {/* Grid Width */}
            <div>
              <label className="block text-lg font-semibold text-gray-700 mb-2">
                Grid Width: {tempConfig.gridWidth || 8} blocks
              </label>
              <input
                type="range"
                min="6"
                max="12"
                value={tempConfig.gridWidth || 8}
                onChange={(e) => setTempConfig({ ...tempConfig, gridWidth: parseInt(e.target.value) })}
                className="w-full h-3 bg-blue-200 rounded-lg appearance-none cursor-pointer"
              />
              <div className="flex justify-between text-sm text-gray-600 mt-1">
                <span>Small (6)</span>
                <span>Large (12)</span>
              </div>
            </div>

            {/* Grid Height */}
            <div>
              <label className="block text-lg font-semibold text-gray-700 mb-2">
                Grid Height: {tempConfig.gridHeight || 10} blocks
              </label>
              <input
                type="range"
                min="8"
                max="14"
                value={tempConfig.gridHeight || 10}
                onChange={(e) => setTempConfig({ ...tempConfig, gridHeight: parseInt(e.target.value) })}
                className="w-full h-3 bg-blue-200 rounded-lg appearance-none cursor-pointer"
              />
              <div className="flex justify-between text-sm text-gray-600 mt-1">
                <span>Short (8)</span>
                <span>Tall (14)</span>
              </div>
            </div>

            {/* Number of Colors */}
            <div>
              <label className="block text-lg font-semibold text-gray-700 mb-2">
                Number of Colors: {tempConfig.initialColors || 4}
              </label>
              <input
                type="range"
                min="3"
                max="6"
                value={tempConfig.initialColors || 4}
                onChange={(e) => setTempConfig({ ...tempConfig, initialColors: parseInt(e.target.value) })}
                className="w-full h-3 bg-blue-200 rounded-lg appearance-none cursor-pointer"
              />
              <div className="flex justify-between text-sm text-gray-600 mt-1">
                <span>Easy (3)</span>
                <span>Hard (6)</span>
              </div>
            </div>
          </div>

          {/* Apply Button */}
          <div className="flex justify-center gap-4 mt-6">
            <button
              className="kid-button bg-green-500 hover:bg-green-600 active:bg-green-700"
              onClick={handleApplySettings}
            >
              ✅ Apply Settings
            </button>
            <button
              className="kid-button bg-gray-500 hover:bg-gray-600 active:bg-gray-700"
              onClick={() => {
                setTempConfig(config);
                setShowSettings(false);
              }}
            >
              ❌ Cancel
            </button>
          </div>
        </div>
      )}

      {/* Instructions - Collapsible on Mobile */}
      <div className="mx-3 mb-4">
        <details className="bg-white rounded-lg shadow-md">
          <summary className="p-3 font-bold text-purple-800 cursor-pointer hover:bg-purple-50 rounded-lg">
            📖 How to Play
          </summary>
          <div className="p-3 pt-0">
            <ul className="space-y-1 text-sm text-gray-700">
              <li className="flex items-start">
                <span className="text-lg mr-2">1️⃣</span>
                <span>Tap a colored block</span>
              </li>
              <li className="flex items-start">
                <span className="text-lg mr-2">2️⃣</span>
                <span>Connected blocks highlight</span>
              </li>
              <li className="flex items-start">
                <span className="text-lg mr-2">3️⃣</span>
                <span>Need 2+ blocks to remove</span>
              </li>
              <li className="flex items-start">
                <span className="text-lg mr-2">4️⃣</span>
                <span>Bigger groups = more points!</span>
              </li>
              <li className="flex items-start">
                <span className="text-lg mr-2">♾️</span>
                <span className="font-semibold">Endless mode!</span>
              </li>
            </ul>
          </div>
        </details>
      </div>
    </GameLayout>
  );
};

export default ColorBlocksPage;

/**
 * Snake Game Page
 * Main container for the Snake game
 */

import React from 'react';
import { useSnakeGame } from '../../../hooks/useSnakeGame';
import { SnakeBoard } from './SnakeBoard';
import { SnakeControls } from './SnakeControls';
import type { Difficulty, GridSize } from './types';
import GameLayout from '../../shared/GameLayout';

interface SnakePageProps {
  onNavigateHome: () => void;
}

const SnakePage: React.FC<SnakePageProps> = ({ onNavigateHome }) => {
  const { gameState, config, controls } = useSnakeGame();

  const handleDifficultyChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    controls.setDifficulty(e.target.value as Difficulty);
  };

  const handleGridSizeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    controls.setGridSize(e.target.value as GridSize);
  };

  const getStatusMessage = (): string => {
    switch (gameState.gameStatus) {
      case 'ready':
        return 'Press any arrow key or tap a direction to start!';
      case 'playing':
        return 'Playing...';
      case 'paused':
        return 'Paused - Press Space or Pause button to resume';
      case 'gameOver':
        return 'Game Over! Press R or Play Again to restart';
      default:
        return '';
    }
  };

  const getStatusColor = (): string => {
    switch (gameState.gameStatus) {
      case 'ready':
        return 'text-blue-600';
      case 'playing':
        return 'text-green-600';
      case 'paused':
        return 'text-yellow-600';
      case 'gameOver':
        return 'text-red-600';
      default:
        return 'text-slate-600';
    }
  };

  return (
    <GameLayout
      title="Snake Game"
      emoji="🐍"
      onNavigateHome={onNavigateHome}
      bgColorClass="bg-gradient-to-b from-emerald-100 to-emerald-200"
      headerActions={
        <>
          <select
            value={gameState.difficulty}
            onChange={handleDifficultyChange}
            disabled={gameState.gameStatus === 'playing'}
            className="kid-input text-xs md:text-sm px-2 md:px-3 py-1 md:py-2"
            title="Game Speed"
          >
            <option value="easy">🐌 Slow</option>
            <option value="medium">🏃 Med</option>
            <option value="hard">⚡ Fast</option>
          </select>

          <select
            value={gameState.gridSize}
            onChange={handleGridSizeChange}
            disabled={gameState.gameStatus === 'playing'}
            className="kid-input text-xs md:text-sm px-2 md:px-3 py-1 md:py-2"
            title="Grid Size"
          >
            <option value="small">📐 15×15</option>
            <option value="medium">📏 20×20</option>
            <option value="large">📊 25×25</option>
            <option value="xlarge">🗺️ 30×30</option>
          </select>

          {(gameState.gameStatus === 'playing' || gameState.gameStatus === 'paused') && (
            <button
              className="kid-button text-xs md:text-sm bg-yellow-500 hover:bg-yellow-600 px-2 md:px-4 py-1 md:py-2"
              onClick={controls.togglePause}
            >
              {gameState.gameStatus === 'paused' ? '▶️' : '⏸️'}
              <span className="hidden md:inline ml-1">{gameState.gameStatus === 'paused' ? 'Resume' : 'Pause'}</span>
            </button>
          )}

          {gameState.gameStatus !== 'ready' && (
            <button
              className="kid-button text-xs md:text-sm bg-blue-500 hover:bg-blue-600 px-2 md:px-4 py-1 md:py-2"
              onClick={controls.resetGame}
            >
              🔄<span className="hidden md:inline ml-1">Play Again</span>
            </button>
          )}
        </>
      }
    >
      {/* Score Display - Compact on mobile */}
      <div className="kid-card max-w-4xl mx-auto mb-2 md:mb-4 p-2 md:p-4">
        <div className="grid grid-cols-3 gap-2 md:gap-4">
          <div className="text-center">
            <p className="text-xs md:text-sm text-slate-600 font-semibold">Score</p>
            <p className="text-xl md:text-3xl font-bold text-lime-600">{gameState.score}</p>
          </div>
          <div className="text-center">
            <p className="text-xs md:text-sm text-slate-600 font-semibold">High</p>
            <p className="text-xl md:text-3xl font-bold text-yellow-600">{gameState.highScore}</p>
          </div>
          <div className="text-center">
            <p className="text-xs md:text-sm text-slate-600 font-semibold">Length</p>
            <p className="text-xl md:text-3xl font-bold text-blue-600">{gameState.snake.length}</p>
          </div>
        </div>
      </div>

      {/* Status Message - Smaller on mobile */}
      <div className="text-center mb-2 md:mb-4">
        <p className={`text-sm md:text-lg font-semibold ${getStatusColor()}`}>
          {getStatusMessage()}
        </p>
      </div>

      {/* Game Board */}
      <div className="mb-2 md:mb-4">
        <SnakeBoard gameState={gameState} config={config} />
      </div>

      {/* Mobile Controls */}
      <div className="md:hidden mb-2">
        <SnakeControls
          onDirectionChange={controls.changeDirection}
          disabled={gameState.gameStatus === 'gameOver' || gameState.gameStatus === 'paused'}
        />
      </div>

      {/* Instructions - Hidden on mobile */}
      <div className="kid-card max-w-4xl mx-auto hidden md:block">
        <h2 className="text-xl font-bold mb-3 text-center text-emerald-800">
          How to Play
        </h2>

        <div className="space-y-3">
          <div>
            <h3 className="font-semibold text-lg mb-1">🎯 Goal</h3>
            <p className="text-slate-700">
              Eat the apples 🍎 to grow your snake and score points. Don't hit the walls or yourself!
            </p>
          </div>

          <div>
            <h3 className="font-semibold text-lg mb-1">⌨️ Keyboard Controls</h3>
            <ul className="text-slate-700 space-y-1">
              <li><strong>Arrow Keys</strong> or <strong>WASD</strong> - Move snake</li>
              <li><strong>Space</strong> - Pause/Resume</li>
              <li><strong>R</strong> - Restart (when game over)</li>
            </ul>
          </div>

          <div className="md:hidden">
            <h3 className="font-semibold text-lg mb-1">📱 Touch Controls</h3>
            <p className="text-slate-700">
              Tap the arrow buttons above to change direction
            </p>
          </div>

          <div>
            <h3 className="font-semibold text-lg mb-1">📊 Scoring</h3>
            <p className="text-slate-700">
              Each apple gives you <strong>+10 points</strong> and makes your snake longer!
            </p>
          </div>

          <div>
            <h3 className="font-semibold text-lg mb-1">⚙️ Game Settings</h3>
            <div className="text-slate-700 space-y-2">
              <div>
                <strong>Speed:</strong>
                <ul className="ml-4 mt-1 space-y-1">
                  <li>🐌 <strong>Slow</strong> - Relaxed pace (200ms)</li>
                  <li>🏃 <strong>Medium</strong> - Moderate speed (150ms)</li>
                  <li>⚡ <strong>Fast</strong> - Quick reflexes needed! (100ms)</li>
                </ul>
              </div>
              <div>
                <strong>Grid Size:</strong>
                <ul className="ml-4 mt-1 space-y-1">
                  <li>📐 <strong>Small</strong> - Cozy 15×15 grid</li>
                  <li>📏 <strong>Medium</strong> - Standard 20×20 grid</li>
                  <li>📊 <strong>Large</strong> - Spacious 25×25 grid</li>
                  <li>🗺️ <strong>X-Large</strong> - Huge 30×30 grid!</li>
                </ul>
              </div>
              <p className="text-sm italic">Mix and match speed and grid size for your perfect challenge!</p>
            </div>
          </div>
        </div>
      </div>

      {/* Game Over Modal Overlay */}
      {gameState.gameStatus === 'gameOver' && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="kid-card max-w-md w-full text-center">
            <h2 className="text-3xl font-bold text-red-600 mb-4">Game Over!</h2>

            <div className="mb-6">
              <p className="text-xl mb-2">Final Score</p>
              <p className="text-5xl font-bold text-lime-600 mb-4">{gameState.score}</p>

              {gameState.score === gameState.highScore && gameState.score > 0 && (
                <p className="text-lg text-yellow-600 font-semibold">
                  🎉 New High Score! 🎉
                </p>
              )}
            </div>

            <div className="flex gap-3 justify-center">
              <button
                className="kid-button bg-lime-500 hover:bg-lime-600 text-lg"
                onClick={controls.resetGame}
              >
                🔄 Play Again
              </button>
              <button
                className="kid-button bg-slate-500 hover:bg-slate-600 text-lg"
                onClick={onNavigateHome}
              >
                ← Home
              </button>
            </div>
          </div>
        </div>
      )}
    </GameLayout>
  );
};

export default SnakePage;

// Main page component for Jelly Volleyball game

import { useJellyVolleyball } from '../../../hooks/useJellyVolleyball';
import GameCanvas from './GameCanvas';
import GameLayout from '../../shared/GameLayout';

interface Props {
  onNavigateHome: () => void;
}

export default function JellyVolleyballPage({ onNavigateHome }: Props) {
  const courtWidth = Math.min(window.innerWidth - 32, 800);
  const courtHeight = courtWidth / 2;
  const { gameState, isPaused, canvasRef, controls } = useJellyVolleyball({
    courtWidth,
    courtHeight,
    netHeight: courtHeight / 4,
    playerRadius: 35,
    ballRadius: 32,
    gravity: 0.06,
    pointsToWin: 7,
  });

  return (
    <GameLayout
      title="Jelly Volleyball"
      emoji="🏐"
      onNavigateHome={onNavigateHome}
      headerActions={
        <button
          className="kid-button text-xs md:text-sm px-2 md:px-4 py-1 md:py-2"
          onClick={controls.togglePause}
        >
          {isPaused ? '▶️ Resume' : '⏸️ Pause'}
        </button>
      }
    >
      {/* Game Canvas */}
      <div className="flex justify-center mb-4">
        <GameCanvas
          ref={canvasRef}
          gameState={gameState}
          width={gameState.court.width}
          height={gameState.court.height}
        />
      </div>

      {/* Controls Info */}
      <div className="kid-card max-w-4xl mx-auto">
        <h2 className="text-xl font-bold mb-3 text-center">How to Play</h2>

        <div className="grid md:grid-cols-2 gap-4">
          {/* Player 1 Controls */}
          <div className="bg-red-100 p-4 rounded-lg border-2 border-red-300">
            <h3 className="font-bold text-lg mb-2 text-red-700">
              🔴 Player 1 (Left - You!)
            </h3>
            <div className="space-y-2 text-sm">
              <div className="flex justify-between">
                <span className="font-semibold">Keyboard:</span>
                <span className="bg-white px-2 py-1 rounded">A/D/← →/W ↑ Space</span>
              </div>
              <div className="flex justify-between">
                <span className="font-semibold">Mouse:</span>
                <span className="bg-white px-2 py-1 rounded">Move + Right-Click to Jump</span>
              </div>
              <div className="flex justify-between">
                <span className="font-semibold">Touch:</span>
                <span className="bg-white px-2 py-1 rounded">Drag + Swipe Up to Jump</span>
              </div>
            </div>

            {/* Touch Controls for Mobile */}
            <div className="mt-3 pt-3 border-t border-red-300">
              <p className="font-semibold mb-2 text-sm">Touch Controls:</p>
              <div className="flex gap-2 justify-center">
                <button
                  className="kid-button text-2xl px-6 py-3"
                  onTouchStart={() => controls.setControl('left', true)}
                  onTouchEnd={() => controls.setControl('left', false)}
                  onMouseDown={() => controls.setControl('left', true)}
                  onMouseUp={() => controls.setControl('left', false)}
                  onMouseLeave={() => controls.setControl('left', false)}
                >
                  ←
                </button>
                <button
                  className="kid-button text-2xl px-6 py-3"
                  onTouchStart={() => controls.setControl('jump', true)}
                  onTouchEnd={() => controls.setControl('jump', false)}
                  onMouseDown={() => controls.setControl('jump', true)}
                  onMouseUp={() => controls.setControl('jump', false)}
                  onMouseLeave={() => controls.setControl('jump', false)}
                >
                  ↑
                </button>
                <button
                  className="kid-button text-2xl px-6 py-3"
                  onTouchStart={() => controls.setControl('right', true)}
                  onTouchEnd={() => controls.setControl('right', false)}
                  onMouseDown={() => controls.setControl('right', true)}
                  onMouseUp={() => controls.setControl('right', false)}
                  onMouseLeave={() => controls.setControl('right', false)}
                >
                  →
                </button>
              </div>
            </div>
          </div>

          {/* Player 2 (AI) Info */}
          <div className="bg-teal-100 p-4 rounded-lg border-2 border-teal-300">
            <h3 className="font-bold text-lg mb-2 text-teal-700">
              🔵 Player 2 (Right - AI)
            </h3>
            <div className="space-y-2 text-sm">
              <p>
                <span className="font-semibold">Controlled by:</span> Computer AI
              </p>
              <p>
                <span className="font-semibold">Difficulty:</span> Medium
              </p>
              <p className="text-xs text-gray-600 mt-2">
                The AI will try to hit the ball back to you. Try to make it land on their side!
              </p>
            </div>
          </div>
        </div>

        {/* Game Rules */}
        <div className="mt-4 p-4 bg-yellow-50 rounded-lg border-2 border-yellow-300">
          <h3 className="font-bold text-lg mb-2 text-yellow-800">📋 Game Rules</h3>
          <ul className="space-y-1 text-sm list-disc list-inside">
            <li>Keep the ball from touching the ground on your side</li>
            <li>Make the ball land on your opponent's side to score</li>
            <li>First player to <strong>{gameState.court.width ? '7' : ''} points</strong> wins!</li>
            <li>The ball must go over the net</li>
            <li>Use your jelly body to bounce the ball</li>
          </ul>
        </div>

        {/* Additional Controls */}
        <div className="mt-4 flex justify-center gap-3">
          <button className="kid-button" onClick={controls.resetGame}>
            🔄 New Game
          </button>
          {isPaused && (
            <div className="text-center py-2 px-4 bg-yellow-100 border-2 border-yellow-400 rounded-lg">
              <span className="font-bold">⏸️ PAUSED</span>
            </div>
          )}
        </div>
      </div>

      {/* Game Status Messages */}
      {gameState.lastScorer && gameState.gameStatus === 'playing' && (
        <div className="fixed top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 pointer-events-none">
          <div className="bg-white border-4 border-blue-500 rounded-lg px-8 py-4 shadow-2xl animate-bounce">
            <p className="text-3xl font-bold text-blue-900">
              {gameState.lastScorer === 1 ? 'You Scored! 🎉' : 'AI Scored! 💪'}
            </p>
          </div>
        </div>
      )}
    </GameLayout>
  );
}

import { useState } from 'react';
import TetrisBoard from './TetrisBoard';
import GameLayout from '../../shared/GameLayout';

interface Props {
  onNavigateHome: () => void;
}

export default function TetrisPage({ onNavigateHome }: Props) {
  const [width, setWidth] = useState(10);
  const [height, setHeight] = useState(20);
  const [appliedWidth, setAppliedWidth] = useState(10);
  const [appliedHeight, setAppliedHeight] = useState(20);

  const changed = appliedWidth !== width || appliedHeight !== height;

  return (
    <GameLayout title="Tetris" emoji="🧱" onNavigateHome={onNavigateHome}>
      <div className="kid-card mb-4 flex flex-wrap items-center gap-3">
        <div className="flex items-center gap-2">
          <label className="text-sm">Width</label>
          <input
            className="kid-input w-16 text-center"
            type="number"
            value={width}
            onChange={(e) => {
              const val = parseInt(e.target.value, 10);
              setWidth(Number.isFinite(val) && val > 0 ? val : 10);
            }}
          />
        </div>
        <div className="flex items-center gap-2">
          <label className="text-sm">Height</label>
          <input
            className="kid-input w-16 text-center"
            type="number"
            value={height}
            onChange={(e) => {
              const val = parseInt(e.target.value, 10);
              setHeight(Number.isFinite(val) && val > 0 ? val : 20);
            }}
          />
        </div>
        <button
          className={`kid-button ${changed ? '' : 'opacity-50 cursor-not-allowed'}`}
          disabled={!changed}
          onClick={() => {
            setAppliedWidth(width);
            setAppliedHeight(height);
          }}
        >
          Apply Size
        </button>
      </div>

      <TetrisBoard key={`${appliedWidth}x${appliedHeight}`} config={{ width: appliedWidth, height: appliedHeight, tickMs: 800 }} />
    </GameLayout>
  );
}

