7	import { useReducer, useEffect, useCallback, useRef } from 'react';
8	import type {
9	  PopBalloonsState,
10	  Balloon,
11	  BalloonType,
12	  Difficulty,
13	  GridSize,
14	} from '../components/Games/PopBalloons/types';
15	import {
16	  difficultySettings,
17	  gridSizeSettings,
18	  POINTS,
19	  balloonColors,
20	  COMBO_WINDOW,
21	} from '../components/Games/PopBalloons/constants';
22	import { saveHighScore, getHighScore, playSound, randomChoice } from '../utils/gameUtils';
23	
24	const GAME_KEY = 'popBalloons';
25	
26	// Internal state — superset of public PopBalloonsState; adds lastPopTime for combo timing
27	interface InternalState extends PopBalloonsState {
28	  lastPopTime: number;
29	}
30	
31	// Discriminated union of all state transitions
32	export type BalloonAction =
33	  | { type: 'RESET'; difficulty: Difficulty; gridSize: GridSize; highScore: number }
34	  | { type: 'START' }
35	  | { type: 'SET_DIFFICULTY'; difficulty: Difficulty }
36	  | { type: 'SET_GRID_SIZE'; gridSize: GridSize }
37	  | { type: 'SPAWN_BALLOON'; balloon: Balloon }
38	  | { type: 'POP_BALLOON'; balloonId: string; now: number }
39	  | { type: 'EXPIRE_BALLOON'; balloonId: string }
40	  | { type: 'TICK' }
41	  | { type: 'LOAD_HIGH_SCORE'; highScore: number };
42	
43	export function makeInitialState(
44	  difficulty: Difficulty,
45	  gridSize: GridSize = 'small',
46	  highScore = 0,
47	): InternalState {
48	  const settings = difficultySettings[difficulty];
49	  return {
50	    difficulty,
51	    gridSize,
52	    balloons: [],
53	    score: 0,
54	    highScore,
55	    combo: 0,
56	    maxCombo: 0,
57	    gameStatus: 'ready',
58	    timeRemaining: settings.gameDuration,
59	    lives: settings.startingLives,
60	    totalPopped: 0,
61	    totalMissed: 0,
62	    lastPopTime: 0,
63	  };
64	}
65	
66	export function balloonReducer(state: InternalState, action: BalloonAction): InternalState {
67	  switch (action.type) {
68	    case 'RESET':
69	      return makeInitialState(action.difficulty, action.gridSize, action.highScore);
70	
71	    case 'START':
72	      return { ...state, gameStatus: 'playing', lastPopTime: Date.now() };
73	
74	    case 'SET_DIFFICULTY':
75	      // Changing difficulty resets the game (matches original initializeGame re-run behaviour)
76	      return makeInitialState(action.difficulty, state.gridSize, state.highScore);
77	
78	    case 'SET_GRID_SIZE':
79	      return { ...state, gridSize: action.gridSize };
80	
81	    case 'SPAWN_BALLOON':
82	      return { ...state, balloons: [...state.balloons, action.balloon] };
83	
84	    case 'POP_BALLOON': {
85	      const balloon = state.balloons.find(b => b.id === action.balloonId);
86	      if (!balloon) return state;
87	
88	      const withoutBalloon = state.balloons.filter(b => b.id !== action.balloonId);
89	
90	      if (balloon.type === 'bomb') {
91	        const newLives = state.lives - 1;
92	        return {
93	          ...state,
94	          balloons: withoutBalloon,
95	          lives: newLives,
96	          combo: 0,
97	          gameStatus: newLives <= 0 ? 'gameOver' : state.gameStatus,
98	        };
99	      }
100	
101	      // Good balloon — compute combo from reducer state (no stale closure)
102	      const timeSinceLastPop = action.now - state.lastPopTime;
103	      const newCombo = timeSinceLastPop < COMBO_WINDOW ? state.combo + 1 : 1;
104	      const basePoints = balloon.type === 'golden' ? POINTS.golden : POINTS.normal;
105	      const comboBonus = newCombo > 1 ? (newCombo - 1) * POINTS.combo : 0;
106	
107	      return {
108	        ...state,
109	        balloons: withoutBalloon,
110	        score: state.score + basePoints + comboBonus,
111	        combo: newCombo,
112	        maxCombo: Math.max(state.maxCombo, newCombo),
113	        totalPopped: state.totalPopped + 1,
114	        lastPopTime: action.now,
115	      };
116	    }
117	
118	    case 'EXPIRE_BALLOON': {
119	      const balloon = state.balloons.find(b => b.id === action.balloonId);
120	      if (!balloon) return state; // Already popped — no-op
121	
122	      const withoutBalloon = state.balloons.filter(b => b.id !== action.balloonId);
123	
124	      if (balloon.type === 'bomb') {
125	        // Bomb expired — no life penalty, but combo resets
126	        return { ...state, balloons: withoutBalloon, combo: 0 };
127	      }
128	
129	      // Normal/golden missed
130	      const newLives = state.lives - 1;
131	      return {
132	        ...state,
133	        balloons: withoutBalloon,
134	        totalMissed: state.totalMissed + 1,
135	        lives: newLives,
136	        combo: 0,
137	        gameStatus: newLives <= 0 ? 'gameOver' : state.gameStatus,
138	      };
139	    }
140	
141	    case 'TICK': {
142	      if (state.timeRemaining <= 1) {
143	        return { ...state, timeRemaining: 0, gameStatus: 'gameOver' };
144	      }
145	      return { ...state, timeRemaining: state.timeRemaining - 1 };
146	    }
147	
148	    case 'LOAD_HIGH_SCORE':
149	      return { ...state, highScore: action.highScore };
150	
151	    default:
152	      return state;
153	  }
154	}
155	
156	interface UsePopBalloonsReturn {
157	  gameState: PopBalloonsState;
158	  handleBalloonPop: (balloonId: string) => void;
159	  startGame: () => void;
160	  resetGame: () => void;
161	  setDifficulty: (difficulty: Difficulty) => void;
162	  setGridSize: (gridSize: GridSize) => void;
163	}
164	
165	export const usePopBalloons = (): UsePopBalloonsReturn => {
166	  const [state, dispatch] = useReducer(balloonReducer, makeInitialState('easy'));
167	
168	  // stateRef — gives setTimeout / setInterval callbacks access to fresh state
169	  // without needing them in their dependency arrays
170	  const stateRef = useRef(state);
171	  useEffect(() => {
172	    stateRef.current = state;
173	  }, [state]);
174	
175	  const spawnTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);
176	  const gameTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);
177	
178	  // ── Load high score whenever difficulty changes (includes mount) ──────────
179	  useEffect(() => {
180	    const saved = getHighScore(`${GAME_KEY}_${state.difficulty}`);
181	    dispatch({ type: 'LOAD_HIGH_SCORE', highScore: saved });
182	  }, [state.difficulty]);
183	
184	  // ── Derive occupied positions from current state (replaces occupiedPositionsRef) ──
185	  const getRandomPosition = useCallback((): { row: number; col: number } | null => {
186	    const { balloons, gridSize } = stateRef.current;
187	    const occupied = new Set(balloons.map(b => `${b.position.row}-${b.position.col}`));
188	    const size = gridSizeSettings[gridSize].size;
189	    const available: { row: number; col: number }[] = [];
190	
191	    for (let row = 0; row < size; row++) {
192	      for (let col = 0; col < size; col++) {
193	        if (!occupied.has(`${row}-${col}`)) available.push({ row, col });
194	      }
195	    }
196	
197	    return available.length === 0 ? null : randomChoice(available);
198	  }, []);
199	
200	  const getBalloonType = useCallback((difficulty: Difficulty): BalloonType => {
201	    const { bombChance, goldenChance } = difficultySettings[difficulty];
202	    const rand = Math.random();
203	    if (rand < bombChance) return 'bomb';
204	    if (rand < bombChance + goldenChance) return 'golden';
205	    return 'normal';
206	  }, []);
207	
208	  // ── Spawn balloon (called from setInterval — reads fresh state via stateRef) ──
209	  const spawnBalloon = useCallback(() => {
210	    const position = getRandomPosition();
211	    if (!position) return; // Grid is full
212	
213	    const { difficulty } = stateRef.current;
214	    const settings = difficultySettings[difficulty];
215	    const type = getBalloonType(difficulty);
216	
217	    const balloon: Balloon = {
218	      id: `balloon-${Date.now()}-${Math.random()}`,
219	      position,
220	      type,
221	      color:
222	        type === 'golden'
223	          ? 'hsl(45, 100%, 60%)'
224	          : type === 'bomb'
225	            ? 'hsl(0, 0%, 30%)'
226	            : randomChoice(balloonColors),
227	      lifetime: settings.balloonLifetime,
228	      spawnTime: Date.now(),
229	    };
230	
231	    dispatch({ type: 'SPAWN_BALLOON', balloon });
232	
233	    // Auto-expire after lifetime — EXPIRE_BALLOON is a no-op if already popped
234	    setTimeout(() => {
235	      dispatch({ type: 'EXPIRE_BALLOON', balloonId: balloon.id });
236	    }, settings.balloonLifetime);
237	  }, [getRandomPosition, getBalloonType]);
238	
239	  // ── Public callbacks ──────────────────────────────────────────────────────
240	
241	  const handleBalloonPop = useCallback((balloonId: string) => {
242	    const balloon = stateRef.current.balloons.find(b => b.id === balloonId);
243	    if (!balloon) return;
244	
245	    // Side-effects (sounds) happen before dispatch — keeps reducer pure
246	    if (balloon.type === 'bomb') {
247	      playSound('lose');
248	    } else {
249	      playSound(balloon.type === 'golden' ? 'collect' : 'pop');
250	    }
251	
252	    dispatch({ type: 'POP_BALLOON', balloonId, now: Date.now() });
253	  }, []);
254	
255	  const startGame = useCallback(() => {
256	    dispatch({ type: 'START' });
257	  }, []);
258	
259	  const resetGame = useCallback(() => {
260	    const { difficulty, gridSize, highScore } = stateRef.current;
261	    dispatch({ type: 'RESET', difficulty, gridSize, highScore });
262	  }, []);
263	
264	  const setDifficulty = useCallback((difficulty: Difficulty) => {
265	    dispatch({ type: 'SET_DIFFICULTY', difficulty });
266	  }, []);
267	
268	  const setGridSize = useCallback((gridSize: GridSize) => {
269	    dispatch({ type: 'SET_GRID_SIZE', gridSize });
270	  }, []);
271	
272	  // ── Spawn interval (re-runs only when play state or difficulty changes) ───
273	  useEffect(() => {
274	    if (state.gameStatus === 'playing') {
275	      spawnBalloon(); // Immediate first spawn
276	
277	      spawnTimerRef.current = setInterval(() => {
278	        spawnBalloon();
279	      }, difficultySettings[state.difficulty].spawnRate);
280	    } else if (spawnTimerRef.current) {
281	      clearInterval(spawnTimerRef.current);
282	      spawnTimerRef.current = null;
283	    }
284	
285	    return () => {
286	      if (spawnTimerRef.current) {
287	        clearInterval(spawnTimerRef.current);
288	        spawnTimerRef.current = null;
289	      }
290	    };
291	  }, [state.gameStatus, state.difficulty, spawnBalloon]);
292	
293	  // ── Game countdown timer ──────────────────────────────────────────────────
294	  useEffect(() => {
295	    if (state.gameStatus === 'playing') {
296	      gameTimerRef.current = setInterval(() => {
297	        dispatch({ type: 'TICK' });
298	      }, 1000);
299	    } else if (gameTimerRef.current) {
300	      clearInterval(gameTimerRef.current);
301	      gameTimerRef.current = null;
302	    }
303	
304	    return () => {
305	      if (gameTimerRef.current) {
306	        clearInterval(gameTimerRef.current);
307	        gameTimerRef.current = null;
308	      }
309	    };
310	  }, [state.gameStatus]);
311	
312	  // ── Persist high score on game over ──────────────────────────────────────
313	  useEffect(() => {
314	    if (state.gameStatus === 'gameOver' && state.score > state.highScore) {
315	      saveHighScore(`${GAME_KEY}_${state.difficulty}`, state.score);
316	      dispatch({ type: 'LOAD_HIGH_SCORE', highScore: state.score });
317	    }
318	  }, [state.gameStatus, state.score, state.highScore, state.difficulty]);
319	
320	  // ── Build public state (omit internal lastPopTime field) ─────────────────
321	  const gameState: PopBalloonsState = {
322	    balloons: state.balloons,
323	    score: state.score,
324	    highScore: state.highScore,
325	    combo: state.combo,
326	    maxCombo: state.maxCombo,
327	    gameStatus: state.gameStatus,
328	    difficulty: state.difficulty,
329	    gridSize: state.gridSize,
330	    timeRemaining: state.timeRemaining,
331	    lives: state.lives,
332	    totalPopped: state.totalPopped,
333	    totalMissed: state.totalMissed,
334	  };
335	
336	  return { gameState, handleBalloonPop, startGame, resetGame, setDifficulty, setGridSize };
337	};
