18	  const stencilMaskRef = useRef<HTMLCanvasElement | null>(null);
19	  const stencilMaskContextRef = useRef<CanvasRenderingContext2D | null>(null);
20	  // Flag to prevent multiple simultaneous stencil drawings
21	  const isDrawingStencilRef = useRef<boolean>(false);
22	  // Store the canvas state after drawing the stencil (so we can restore it)
23	  const stencilCanvasStateRef = useRef<ImageData | null>(null);
24	  
25	  // Reactive state for UI components
26	  const [currentColor, setCurrentColorState] = useState('#FF6B6B');
27	  const [currentLineWidth, setCurrentLineWidthState] = useState(4);
28	  const [currentTool, setCurrentToolState] = useState<'brush' | 'fill'>('brush');
29	  
