31	    isDrawing: false,
32	    currentPath: [],
33	    paths: [],
34	    currentColor: '#FF6B6B', // Default red color
35	    currentLineWidth: 4
36	  });
37	
38	  // Draw stencil SVG path on canvas and mask (with duplicate prevention)
39	  const drawStencil = useCallback((context: CanvasRenderingContext2D, stencil: Stencil) => {
40	    // Prevent multiple simultaneous stencil drawings
41	    if (isDrawingStencilRef.current) {
42	      console.log('Skipping stencil draw - already in progress');
43	      return;
44	    }
45	    
46	    
47	    isDrawingStencilRef.current = true;
48	    
49	    try {
