51	      
52	      // Get device pixel ratio for high-DPI stencil rendering
53	      const devicePixelRatio = window.devicePixelRatio || 1;
54	      
55	      // Clear canvas before drawing to prevent overlaps (use display dimensions)
56	      context.fillStyle = '#FFFFFF';
57	      context.fillRect(0, 0, width, height);
58	      
