85	        // Scale the stencil to fill the viewport, allowing parts to be cut off
86	        const scale = Math.min((width * 1.3) / viewWidth, (height * 1.3) / viewHeight);
87	        const scaledWidth = viewWidth * scale;
88	        const scaledHeight = viewHeight * scale;
89	        const x = (width - scaledWidth) / 2;
90	        const y = (height - scaledHeight) / 2;
91	
92	        
93	        // Draw on visible canvas
94	        context.drawImage(img, x, y, scaledWidth, scaledHeight);
95	        
96	        // Draw on mask canvas if available (maximum precision collision detection)
97	        if (maskContext) {
98	          // Create the thinnest possible mask for maximum coloring precision
99	          const maskStrokeWidth = Math.max(0.4, 0.5 * devicePixelRatio);
100	          const maskSvgString = `
101	            <svg viewBox="${stencil.viewBox}" xmlns="http://www.w3.org/2000/svg">
102	              <path d="${stencil.svgPath}" 
103	                    fill="none" 
104	                    stroke="#FF0000" 
105	                    stroke-width="${maskStrokeWidth}" 
106	                    stroke-linecap="round" 
107	                    stroke-linejoin="round"/>
108	            </svg>
109	          `;
110	          
111	          const maskImg = new Image();
112	          maskImg.onload = () => {
113	            maskContext.drawImage(maskImg, x, y, scaledWidth, scaledHeight);
114	          };
115	          
116	          maskImg.onerror = (error) => {
117	            console.error('Mask image failed to load:', error);
118	          };
119	          
120	          const maskSvgDataUrl = `data:image/svg+xml;base64,${btoa(maskSvgString)}`;
121	          maskImg.src = maskSvgDataUrl;
122	        }
123	        
124	        // Save the canvas state with the stencil drawn
125	        const canvas = canvasRef.current;
126	        if (canvas) {
127	          stencilCanvasStateRef.current = context.getImageData(0, 0, canvas.width, canvas.height);
128	        }
129	        
130	        // Notify parent component of changes
131	        if (onDrawingChange) {
132	          onDrawingChange(canvasRef.current!.toDataURL('image/png'));
133	        }
134	        
135	        // Reset the flag when drawing is complete
136	        isDrawingStencilRef.current = false;
137	      };
138	      
139	      img.onerror = (error) => {
140	        console.error('Stencil image failed to load:', error);
141	        isDrawingStencilRef.current = false; // Reset flag on error too
142	      };
143	
144	      // Use data URL for better compatibility
145	      const svgDataUrl = `data:image/svg+xml;base64,${btoa(svgString)}`;
146	      img.src = svgDataUrl;
147	      
148	    } catch (error) {
149	      console.error('Error in drawStencil:', error);
