151	    }
152	  }, [width, height, onDrawingChange]);
153	
154	  // Check if a point is on the stencil outline (protected area)
155	  const isPointOnStencil = useCallback((x: number, y: number): boolean => {
156	    const maskContext = stencilMaskContextRef.current;
157	    if (!maskContext || !stencil) return false;
158	    
159	    try {
160	      // Convert display coordinates to internal canvas pixel coordinates
161	      const devicePixelRatio = window.devicePixelRatio || 1;
162	      const pixelX = Math.floor(x * devicePixelRatio);
163	      const pixelY = Math.floor(y * devicePixelRatio);
164	      
165	      // Get pixel data at the scaled point
166	      const imageData = maskContext.getImageData(pixelX, pixelY, 1, 1);
167	      const data = imageData.data;
168	      
169	      // Check if pixel is not transparent (alpha > 0)
170	      // The mask uses red color, so we check if red channel > 0
171	      return data[0] > 0; // Red channel
172	    } catch (error) {
