174	      return false;
175	    }
176	  }, [stencil]);
177	
178	  // Initialize canvas context
179	  useEffect(() => {
180	    const canvas = canvasRef.current;
181	    if (!canvas) return;
182	
183	    const context = canvas.getContext('2d');
184	    if (!context) return;
