209	      stencilMaskRef.current = document.createElement('canvas');
210	    }
211	    const maskCanvas = stencilMaskRef.current;
212	    maskCanvas.width = width * devicePixelRatio;
213	    maskCanvas.height = height * devicePixelRatio;
214	    
215	    const maskContext = maskCanvas.getContext('2d');
216	    if (maskContext) {
