359	    const startPos = (pixelY * canvas.width + pixelX) * 4;
360	    const startR = pixels[startPos];
361	    const startG = pixels[startPos + 1];
362	    const startB = pixels[startPos + 2];
363	    const startA = pixels[startPos + 3];
364	
365	    // If start color is the same as fill color, no need to fill
366	    if (startR === fillRgb.r && startG === fillRgb.g && startB === fillRgb.b) {
367	      return;
368	    }
369	
370	    // Flood fill using stack-based approach (more efficient than recursion)
371	    const stack: Array<[number, number]> = [[pixelX, pixelY]];
372	    const visited = new Set<string>();
373	
374	    while (stack.length > 0) {
375	      const [x, y] = stack.pop()!;
376	      
377	      // Skip if out of bounds
378	      if (x < 0 || x >= canvas.width || y < 0 || y >= canvas.height) continue;
379	      
380	      // Skip if already visited
381	      const key = `${x},${y}`;
382	      if (visited.has(key)) continue;
383	      visited.add(key);
384	
385	      const pos = (y * canvas.width + x) * 4;
386	      const r = pixels[pos];
387	      const g = pixels[pos + 1];
388	      const b = pixels[pos + 2];
389	      const a = pixels[pos + 3];
390	
391	      // Skip if color doesn't match the start color
392	      if (r !== startR || g !== startG || b !== startB || a !== startA) continue;
393	
394	      // Fill the pixel
395	      pixels[pos] = fillRgb.r;
396	      pixels[pos + 1] = fillRgb.g;
397	      pixels[pos + 2] = fillRgb.b;
398	      pixels[pos + 3] = 255; // Full opacity
399	
400	      // Add neighboring pixels to stack
401	      stack.push([x + 1, y]);
402	      stack.push([x - 1, y]);
403	      stack.push([x, y + 1]);
404	      stack.push([x, y - 1]);
405	    }
