416	  // Helper function to convert hex color to RGB
417	  const hexToRgb = (hex: string): { r: number; g: number; b: number } | null => {
418	    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
419	    return result ? {
420	      r: parseInt(result[1], 16),
421	      g: parseInt(result[2], 16),
422	      b: parseInt(result[3], 16)
