1	import { describe, test, expect, vi, beforeEach } from 'vitest';
2	import { renderHook, act } from '@testing-library/react';
3	import { useDrawings } from './useDrawings';
4	import * as storage from '../utils/storage';
5	
6	vi.mock('../utils/storage', () => ({
7	  get: vi.fn(() => []),
8	  set: vi.fn(),
9	  remove: vi.fn(),
10	  migrate: vi.fn(),
11	}));
12	
13	describe('useDrawings', () => {
14	  beforeEach(() => {
15	    vi.clearAllMocks();
16	    vi.mocked(storage.get).mockReturnValue([]);
17	  });
18	
19	  test('save() adds a drawing to the list and persists to storage', () => {
20	    const { result } = renderHook(() => useDrawings());
21	
22	    act(() => {
23	      result.current.save('data:image/png;base64,abc123');
24	    });
25	
26	    expect(result.current.drawings).toHaveLength(1);
27	    expect(result.current.drawings[0].dataURL).toBe('data:image/png;base64,abc123');
28	    expect(storage.set).toHaveBeenCalledTimes(1);
29	  });
30	
31	  test('remove() filters out the drawing by id', () => {
32	    const { result } = renderHook(() => useDrawings());
33	    let savedId = '';
34	
35	    act(() => {
36	      const drawing = result.current.save('data:image/png;base64,remove-me');
37	      savedId = drawing.id;
38	    });
39	
40	    act(() => {
41	      result.current.remove(savedId);
42	    });
43	
44	    expect(result.current.drawings).toHaveLength(0);
45	  });
46	
47	  test('clear() empties all drawings and removes from storage', () => {
48	    const { result } = renderHook(() => useDrawings());
49	
50	    act(() => {
51	      result.current.save('data:image/png;base64,one');
52	    });
53	    act(() => {
54	      result.current.save('data:image/png;base64,two');
55	    });
56	    act(() => {
57	      result.current.clear();
58	    });
