import { useState } from 'react';
import ColorPicker from './ColorPicker';
import BrushSizePicker from './BrushSizePicker';
import ToolSelector from './ToolSelector';
import { isMobileDevice } from '../../utils/DeviceUtils';

interface DrawingToolPanelProps {
  currentColor: string;
  currentBrushSize: number;
  currentTool: 'brush' | 'fill';
  onColorChange: (color: string) => void;
  onBrushSizeChange: (size: number) => void;
  onToolChange: (tool: 'brush' | 'fill') => void;
  onClearCanvas: () => void;
  onUndo?: () => void;
  onRedo?: () => void;
  canUndo?: boolean;
  canRedo?: boolean;
}

const DrawingToolPanel = ({
  currentColor,
  currentBrushSize,
  currentTool,
  onColorChange,
  onBrushSizeChange,
  onToolChange,
  onClearCanvas,
  onUndo,
  onRedo,
  canUndo = false,
  canRedo = false,
}: DrawingToolPanelProps) => {
  const isMobile = isMobileDevice();
  const [showBrushSizePicker, setShowBrushSizePicker] = useState(false);

  const handleBrushOptionsToggle = () => {
    setShowBrushSizePicker(!showBrushSizePicker);
  };

  const handleBrushSizeChange = (size: number) => {
    onBrushSizeChange(size);
    setShowBrushSizePicker(false); // Hide picker after selection
  };

  if (isMobile) {
    // Mobile: Return separate components for top and bottom bars
    return (
      <>
        {/* Top Bar - Tool Selector, Colors, Undo/Redo */}
        <div className="bg-white border-b border-gray-200 px-4 py-3">
          <div className="flex items-center justify-between gap-2">
            {/* Tool Selector */}
            <div className="flex-shrink-0 relative">
              <ToolSelector
                selectedTool={currentTool}
                onToolChange={onToolChange}
                onBrushOptionsToggle={handleBrushOptionsToggle}
              />

              {/* Brush Size Picker Popup */}
              {showBrushSizePicker && (
                <div className="absolute top-full mt-2 left-0 bg-white rounded-lg shadow-lg border border-gray-200 p-3 z-50">
                  <BrushSizePicker
                    selectedSize={currentBrushSize}
                    onSizeChange={handleBrushSizeChange}
                  />
                </div>
              )}
            </div>

            {/* Colors */}
            <div className="flex-1 px-2">
              <ColorPicker
                selectedColor={currentColor}
                onColorChange={onColorChange}
              />
            </div>

            {/* Undo / Redo */}
            <div className="flex gap-1 flex-shrink-0">
              <button
                onClick={onUndo}
                disabled={!canUndo}
                aria-label="Undo"
                className="kid-button text-xl px-3 py-2 disabled:opacity-40 disabled:cursor-not-allowed"
              >
                ↩️
              </button>
              <button
                onClick={onRedo}
                disabled={!canRedo}
                aria-label="Redo"
                className="kid-button text-xl px-3 py-2 disabled:opacity-40 disabled:cursor-not-allowed"
              >
                ↪️
              </button>
            </div>
          </div>
        </div>
      </>
    );
  }

  // Desktop: Keep the existing centered layout
  return (
    <div className="mb-6">
      <div className="bg-white rounded-2xl shadow-lg border-2 border-gray-100 overflow-hidden max-w-2xl mx-auto">
        <div className="p-4">
          <h2 className="text-lg font-bold text-center text-gray-800 mb-4">
            🎨 Drawing Tools
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="flex-1 relative">
              <ToolSelector 
                selectedTool={currentTool} 
                onToolChange={onToolChange}
                onBrushOptionsToggle={handleBrushOptionsToggle}
              />

              {/* Brush Size Picker Popup */}
              {showBrushSizePicker && (
                <div className="absolute top-full mt-2 left-1/2 transform -translate-x-1/2 bg-white rounded-lg shadow-lg border border-gray-200 p-3 z-50">
                  <BrushSizePicker 
                    selectedSize={currentBrushSize} 
                    onSizeChange={handleBrushSizeChange} 
                  />
                </div>
              )}
            </div>

            <div className="flex-1">
              <ColorPicker 
                selectedColor={currentColor} 
                onColorChange={onColorChange} 
              />
            </div>
          </div>

          {/* Action buttons */}
          <div className="flex justify-center gap-3 mt-4 pt-4 border-t border-gray-100">
            <button
              onClick={onUndo}
              disabled={!canUndo}
              aria-label="Undo"
              className="kid-button bg-indigo-500 hover:bg-indigo-600 active:bg-indigo-700 text-base px-4 py-3 disabled:opacity-40 disabled:cursor-not-allowed"
            >
              ↩️ Undo
            </button>
            <button
              onClick={onRedo}
              disabled={!canRedo}
              aria-label="Redo"
              className="kid-button bg-indigo-500 hover:bg-indigo-600 active:bg-indigo-700 text-base px-4 py-3 disabled:opacity-40 disabled:cursor-not-allowed"
            >
              ↪️ Redo
            </button>
            <button
              onClick={onClearCanvas}
              className="kid-button bg-red-500 hover:bg-red-600 active:bg-red-700 text-base px-6 py-3 flex items-center gap-2"
            >
              <span>🗑️</span>
              Clear Canvas
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DrawingToolPanel;

import { useState, useCallback, useEffect } from 'react';
import { useCanvas } from '../../hooks/useCanvas';
import DrawingToolPanel from '../Tools/DrawingToolPanel';
import { CanvasProps } from '../../types/Drawing';
import { isMobileDevice } from '../../utils/DeviceUtils';

const DrawingCanvasWithTools = ({
  width = 800,
  height = 600,
  className = '',
  onDrawingChange,
  clearCanvasRef,
  stencil,
  initialDataURL,
}: CanvasProps) => {
  const [isMobile] = useState(isMobileDevice());

  const {
    canvasRef,
    startDrawing,
    draw,
    stopDrawing,
    setColor,
    setLineWidth,
    setTool,
    clearCanvas,
    currentColor,
    currentLineWidth,
    currentTool,
    undo,
    redo,
    canUndo,
    canRedo,
  } = useCanvas({ width, height, onDrawingChange, stencil, initialDataURL });

  const handleColorChange = useCallback((color: string) => {
    setColor(color);
  }, [setColor]);

  const handleBrushSizeChange = useCallback((size: number) => {
    setLineWidth(size);
  }, [setLineWidth]);

  const handleToolChange = useCallback((tool: 'brush' | 'fill') => {
    setTool(tool);
  }, [setTool]);

  const handleClearCanvas = useCallback(() => {
    clearCanvas();
  }, [clearCanvas]);

  // Set the clear function in the ref so parent can call it
  useEffect(() => {
    if (clearCanvasRef) {
      clearCanvasRef.current = handleClearCanvas;
    }
  }, [clearCanvasRef, handleClearCanvas]);

  const handleTouchStart = (e: React.TouchEvent) => {
    startDrawing(e);
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    draw(e);
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
    stopDrawing(e);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    startDrawing(e);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    draw(e);
  };

  const handleMouseUp = (e: React.MouseEvent) => {
    stopDrawing(e);
  };

  // Dynamic canvas styling based on device type
  const canvasClassName = isMobile 
    ? "bg-white touch-none select-none rounded-lg shadow-sm" // Mobile: no border, subtle shadow
    : "border-4 border-primary-200 rounded-2xl bg-white touch-none select-none shadow-lg"; // Desktop: decorative border

  if (isMobile) {
    // Mobile: Full-screen layout with top/bottom tool bars
    return (
      <div className="flex flex-col h-full">
        {/* Top Tool Bar */}
        <DrawingToolPanel
          currentColor={currentColor}
          currentBrushSize={currentLineWidth}
          currentTool={currentTool}
          onColorChange={handleColorChange}
          onBrushSizeChange={handleBrushSizeChange}
          onToolChange={handleToolChange}
          onClearCanvas={handleClearCanvas}
          onUndo={undo}
          onRedo={redo}
          canUndo={canUndo}
          canRedo={canRedo}
        />

        {/* Canvas Area - takes remaining space */}
        <div className="flex-1 flex items-center justify-center p-4">
          <canvas
            ref={canvasRef}
            width={width}
            height={height}
            className={canvasClassName}
            style={{ touchAction: 'none' }}
            data-testid="drawing-canvas"
            onTouchStart={handleTouchStart}
            onTouchMove={handleTouchMove}
            onTouchEnd={handleTouchEnd}
            onMouseDown={handleMouseDown}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onMouseLeave={handleMouseUp}
          />
        </div>

        {/* Bottom Tool Bar (second part from DrawingToolPanel) */}
        {/* Note: This is rendered as part of DrawingToolPanel's fragment */}
      </div>
    );
  }

  // Desktop: Keep the existing centered layout
  return (
    <div className="flex flex-col items-center">
      {/* Drawing Tools Panel */}
      <DrawingToolPanel
        currentColor={currentColor}
        currentBrushSize={currentLineWidth}
        currentTool={currentTool}
        onColorChange={handleColorChange}
        onBrushSizeChange={handleBrushSizeChange}
        onToolChange={handleToolChange}
        onClearCanvas={handleClearCanvas}
          onUndo={undo}
          onRedo={redo}
          canUndo={canUndo}
          canRedo={canRedo}
      />

      {/* Canvas */}
      <div className={`relative ${className} mb-4`}>
        <canvas
          ref={canvasRef}
          width={width}
          height={height}
          className={canvasClassName}
          style={{ touchAction: 'none' }}
          data-testid="drawing-canvas"
          onTouchStart={handleTouchStart}
          onTouchMove={handleTouchMove}
          onTouchEnd={handleTouchEnd}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp} // Stop drawing when mouse leaves canvas
        />
      </div>
    </div>
  );
};

export default DrawingCanvasWithTools;

/**
 * useCanvas – undo/redo history tests
 *
 * The canvas API is mocked at the prototype level so the hook's snapshot
 * capture (`toDataURL`) returns distinct, counter-based values and
 * `applySnapshot`'s Image load fires synchronously.
 */

import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, act } from '@testing-library/react';
import React from 'react';
import { useCanvas } from './useCanvas';
import type { Stencil } from '../types/Stencil';

// ── Canvas context mock ─────────────────────────────────────────────────────

const ctxMock = {
  fillRect: vi.fn(),
  fillStyle: '#fff',
  drawImage: vi.fn(),
  clearRect: vi.fn(),
  scale: vi.fn(),
  beginPath: vi.fn(),
  moveTo: vi.fn(),
  lineTo: vi.fn(),
  stroke: vi.fn(),
  getImageData: vi.fn(() => ({ data: new Uint8ClampedArray(4) })),
  putImageData: vi.fn(),
  strokeStyle: '',
  lineWidth: 1,
  lineCap: 'round',
  lineJoin: 'round',
  imageSmoothingEnabled: true,
};

// Image that fires onload synchronously when src is assigned (avoids async issues)
class SyncImage {
  onload: (() => void) | null = null;
  onerror: (() => void) | null = null;
  width = 100;
  height = 100;
  set src(_: string) {
    this.onload?.();
  }
}

// ── Wrapper component ───────────────────────────────────────────────────────

type HookHandle = { current: ReturnType<typeof useCanvas> | null };

function CanvasHarness({
  handle,
  stencil = null,
}: {
  handle: HookHandle;
  stencil?: Stencil | null;
}) {
  const hook = useCanvas({ width: 100, height: 100, stencil });
  handle.current = hook;
  return React.createElement('canvas', { ref: hook.canvasRef, 'data-testid': 'test-canvas' });
}

// ── Helpers ─────────────────────────────────────────────────────────────────

let snapCounter = 0;

function makeMockEvent(x = 10, y = 10): React.MouseEvent {
  return {
    preventDefault: vi.fn(),
    clientX: x,
    clientY: y,
  } as unknown as React.MouseEvent;
}

/** Always reads functions from handle.current so we get the latest callback references. */
function simulateStroke(handle: HookHandle) {
  act(() => { handle.current!.startDrawing(makeMockEvent(10, 10)); });
  act(() => { handle.current!.draw(makeMockEvent(20, 20)); });
  act(() => { handle.current!.stopDrawing(makeMockEvent(20, 20)); });
}

// ── Suite ───────────────────────────────────────────────────────────────────

describe('useCanvas undo/redo', () => {
  beforeEach(() => {
    snapCounter = 0;
    vi.stubGlobal('Image', SyncImage);

    vi.spyOn(HTMLCanvasElement.prototype, 'getContext').mockReturnValue(
      ctxMock as unknown as CanvasRenderingContext2D,
    );
    vi.spyOn(HTMLCanvasElement.prototype, 'toDataURL').mockImplementation(
      () => `data:image/jpeg;base64,snap-${++snapCounter}`,
    );
    vi.spyOn(Element.prototype, 'getBoundingClientRect').mockReturnValue({
      left: 0, top: 0, right: 100, bottom: 100,
      width: 100, height: 100, x: 0, y: 0,
      toJSON: () => ({}),
    } as DOMRect);
  });

  afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
  });

  test('undo after clear', () => {
    const handle: HookHandle = { current: null };
    render(React.createElement(CanvasHarness, { handle }));

    // Draw a stroke so the canvas has content
    simulateStroke(handle);
    expect(handle.current!.canUndo).toBe(true);

    const drawImageCallsBefore = ctxMock.drawImage.mock.calls.length;

    // Clear the canvas — pre-clear state is pushed to history
    act(() => { handle.current!.clearCanvas(); });

    // Undo the clear — hook must call drawImage to restore the previous frame
    act(() => { handle.current!.undo(); });
    expect(ctxMock.drawImage.mock.calls.length).toBeGreaterThan(drawImageCallsBefore);
  });

  test('undo during stencil overlay', () => {
    const handle: HookHandle = { current: null };
    const { rerender } = render(React.createElement(CanvasHarness, { handle }));

    // No history on initial blank mount
    expect(handle.current!.canUndo).toBe(false);

    // Apply a stencil — the stencil-tracking effect must push pre-stencil state
    const stencil: Stencil = {
      id: 'test-1',
      name: 'Test',
      svgPath: 'M0,0 L10,10',
      viewBox: '0 0 100 100',
      category: 'animals',
      thumbnail: '',
      description: 'test stencil',
    };
    act(() => {
      rerender(React.createElement(CanvasHarness, { handle, stencil }));
    });

    // After applying the stencil, we should be able to undo it
    expect(handle.current!.canUndo).toBe(true);

    const drawImageCallsBefore = ctxMock.drawImage.mock.calls.length;

    // Undo restores the pre-stencil (blank) canvas
    act(() => { handle.current!.undo(); });
    expect(handle.current!.canUndo).toBe(false);
    expect(ctxMock.drawImage.mock.calls.length).toBeGreaterThan(drawImageCallsBefore);
  });

  test('redo after new stroke invalidates forward history', () => {
    const handle: HookHandle = { current: null };
    render(React.createElement(CanvasHarness, { handle }));

    // Stroke + undo creates a redo entry
    simulateStroke(handle);
    act(() => { handle.current!.undo(); });
    expect(handle.current!.canRedo).toBe(true);

    // A new stroke must invalidate all forward history
    simulateStroke(handle);
    expect(handle.current!.canRedo).toBe(false);
  });

  test('history capped at 20', () => {
    const handle: HookHandle = { current: null };
    render(React.createElement(CanvasHarness, { handle }));

    // 21 strokes — history should cap at 20 (oldest frame evicted)
    for (let i = 0; i < 21; i++) {
      simulateStroke(handle);
    }

    // Undo until exhausted
    let undoCount = 0;
    while (handle.current!.canUndo && undoCount < 25) {
      act(() => { handle.current!.undo(); });
      undoCount++;
    }

    // Exactly 20 undos possible — 21st frame was evicted
    expect(undoCount).toBe(20);
    expect(handle.current!.canUndo).toBe(false);
  });
});

/**
 * Memory Match Game Page
 * Main container for the Memory Match game
 */

import React, { useEffect } from 'react';
import { useMemoryMatch } from '../../../hooks/useMemoryMatch';
import GameLayout from '../../shared/GameLayout';
import GameBoard from './GameBoard';
import type { Difficulty, Theme } from './types';
import { difficultySettings, themeNames } from './themes';
import { formatTime, celebrateWin, getStatusColor } from '../../../utils/gameUtils';

interface MemoryMatchPageProps {
  onNavigateHome: () => void;
}

const MemoryMatchPage: React.FC<MemoryMatchPageProps> = ({ onNavigateHome }) => {
  const { gameState, handleCardClick, resetGame, setDifficulty, setTheme } = useMemoryMatch();

  const {
    moves,
    timer,
    bestTime,
    gameStatus,
    difficulty,
    theme,
    matchedPairs
  } = gameState;

  const totalPairs = difficultySettings[difficulty].pairs;
  const progress = (matchedPairs.size / totalPairs) * 100;

  // Celebrate on win
  useEffect(() => {
    if (gameStatus === 'completed') {
      celebrateWin();
    }
  }, [gameStatus]);

  const handleThemeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    if (gameStatus !== 'playing') {
      setTheme(e.target.value as Theme);
    }
  };

  const getStatusMessage = (): string => {
    switch (gameStatus) {
      case 'ready':
        return '🎯 Click any card to start!';
      case 'playing':
        return '🧠 Find all the matching pairs!';
      case 'completed':
        return '🎉 You won! Congratulations!';
      default:
        return '';
    }
  };

  const headerActions = (
    <>
      {/* Difficulty Selector - Emoji buttons */}
      <div className="flex gap-1" title="Game Difficulty">
        {(['easy', 'medium', 'hard'] as const).map(d => (
          <button
            key={d}
            aria-label={d === 'easy' ? 'Easy' : d === 'medium' ? 'Medium' : 'Hard'}
            onClick={() => { if (gameStatus !== 'playing') setDifficulty(d as Difficulty); }}
            disabled={gameStatus === 'playing'}
            className={`kid-button text-base md:text-lg px-2 md:px-3 py-1 md:py-2 ${
              difficulty === d ? '' : 'opacity-50'
            }`}
          >
            {d === 'easy' ? '🐣' : d === 'medium' ? '🐱' : '🦁'}
          </button>
        ))}
      </div>

      {/* Theme Selector - Compact on mobile */}
      <select
        value={theme}
        onChange={handleThemeChange}
        disabled={gameStatus === 'playing'}
        className="kid-input text-xs md:text-sm px-2 md:px-3 py-1 md:py-2"
        title="Card Theme"
      >
        {Object.entries(themeNames).map(([key, name]) => (
          <option key={key} value={key}>
            {name}
          </option>
        ))}
      </select>

      {/* New Game Button - Compact on mobile */}
      <button
        className="kid-button text-xs md:text-sm bg-blue-500 hover:bg-blue-600 px-2 md:px-4 py-1 md:py-2"
        onClick={resetGame}
      >
        <span className="md:hidden">🔄</span>
        <span className="hidden md:inline">🔄 New Game</span>
      </button>
    </>
  );

  return (
    <GameLayout
      title="Memory Match"
      emoji="🃏"
      onNavigateHome={onNavigateHome}
      headerActions={headerActions}
      bgColorClass="bg-gradient-to-b from-pink-100 to-purple-100"
    >
      {/* Stats Panel - Compact on mobile */}
      <div className="kid-card max-w-4xl mx-auto mb-2 md:mb-4 p-2 md:p-4">
        <div className="grid grid-cols-3 gap-2 md:gap-4">
          {/* Moves */}
          <div className="text-center">
            <p className="text-xs md:text-sm text-slate-600 font-semibold">Moves</p>
            <p className="text-xl md:text-3xl font-bold text-blue-600">{moves}</p>
          </div>

          {/* Timer */}
          <div className="text-center">
            <p className="text-xs md:text-sm text-slate-600 font-semibold">Time</p>
            <p className="text-xl md:text-3xl font-bold text-purple-600">
              {formatTime(timer)}
            </p>
          </div>

          {/* Best Time */}
          <div className="text-center">
            <p className="text-xs md:text-sm text-slate-600 font-semibold">Best</p>
            <p className="text-xl md:text-3xl font-bold text-yellow-600">
              {bestTime > 0 ? formatTime(bestTime) : '--:--'}
            </p>
          </div>
        </div>

        {/* Progress Bar - Smaller on mobile */}
        <div className="mt-2 md:mt-4">
          <div className="flex justify-between text-xs md:text-sm text-slate-600 mb-1">
            <span>Progress</span>
            <span>{matchedPairs.size} / {totalPairs}</span>
          </div>
          <div className="w-full bg-slate-200 rounded-full h-2 md:h-4 overflow-hidden">
            <div
              className="bg-gradient-to-r from-blue-500 to-purple-500 h-full transition-all duration-300 rounded-full"
              style={{ width: `${progress}%` }}
            />
          </div>
        </div>
      </div>

      {/* Status Message - Smaller on mobile */}
      <div className="text-center mb-2 md:mb-4">
        <p className={`text-sm md:text-lg font-semibold ${getStatusColor(gameStatus, { playing: 'text-purple-600' })}`}>
          {getStatusMessage()}
        </p>
      </div>

      {/* Game Board */}
      <div className="mb-2 md:mb-6">
        <GameBoard gameState={gameState} onCardClick={handleCardClick} />
      </div>

      {/* Instructions - Hidden on mobile, visible on larger screens */}
      <div className="kid-card max-w-4xl mx-auto hidden md:block">
        <h2 className="text-xl font-bold mb-3 text-center text-purple-800">
          How to Play
        </h2>

        <div className="space-y-3 text-slate-700">
          <div>
            <h3 className="font-semibold text-lg mb-1">🎯 Goal</h3>
            <p>
              Find all matching pairs of cards by remembering where each card is located!
            </p>
          </div>

          <div>
            <h3 className="font-semibold text-lg mb-1">🎮 How to Play</h3>
            <ul className="list-disc list-inside space-y-1">
              <li>Click on a card to flip it over</li>
              <li>Click on a second card to see if they match</li>
              <li>If they match, they stay face up! ✓</li>
              <li>If they don't match, they flip back</li>
              <li>Try to find all pairs in the fewest moves!</li>
            </ul>
          </div>

          <div>
            <h3 className="font-semibold text-lg mb-1">⚙️ Settings</h3>
            <ul className="list-disc list-inside space-y-1">
              <li><strong>Easy:</strong> 6 pairs (4x3 grid)</li>
              <li><strong>Medium:</strong> 8 pairs (4x4 grid)</li>
              <li><strong>Hard:</strong> 12 pairs (4x6 grid)</li>
            </ul>
            <p className="mt-2 text-sm italic">
              Choose your favorite theme and challenge level before starting!
            </p>
          </div>

          <div>
            <h3 className="font-semibold text-lg mb-1">💡 Tips</h3>
            <ul className="list-disc list-inside space-y-1">
              <li>Pay attention to where each card is!</li>
              <li>Try to remember patterns</li>
              <li>The fewer moves, the better your score</li>
              <li>Beat your best time!</li>
            </ul>
          </div>
        </div>
      </div>

      {/* Completion Modal */}
      {gameStatus === 'completed' && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="kid-card max-w-md w-full text-center">
            <div className="text-6xl mb-4">🎉</div>
            <h2 className="text-3xl font-bold text-green-600 mb-4">
              You Won!
            </h2>

            <div className="mb-6 space-y-3">
              <div>
                <p className="text-lg text-slate-600">Total Moves</p>
                <p className="text-4xl font-bold text-blue-600">{moves}</p>
              </div>

              <div>
                <p className="text-lg text-slate-600">Time</p>
                <p className="text-4xl font-bold text-purple-600">
                  {formatTime(timer)}
                </p>
              </div>

              {timer === bestTime && bestTime > 0 && (
                <div className="bg-yellow-100 border-2 border-yellow-400 rounded-lg p-3">
                  <p className="text-lg text-yellow-800 font-semibold">
                    🏆 New Best Time! 🏆
                  </p>
                </div>
              )}
            </div>

            <div className="flex gap-3 justify-center">
              <button
                className="kid-button bg-purple-500 hover:bg-purple-600 text-lg"
                onClick={resetGame}
              >
                🔄 Play Again
              </button>
              <button
                className="kid-button bg-slate-500 hover:bg-slate-600 text-lg"
                onClick={onNavigateHome}
              >
                ← Home
              </button>
            </div>
          </div>
        </div>
      )}
    </GameLayout>
  );
};

export default MemoryMatchPage;

