2	 * Color Mixer Game Tests
3	 */
4	
5	import { describe, test, expect } from 'vitest';
6	import { renderHook, act } from '@testing-library/react';
7	import { useColorMixer } from '../../../../hooks/useColorMixer';
8	
9	describe('useColorMixer Hook', () => {
10	  test('initializes with correct default state', () => {
11	    const { result } = renderHook(() => useColorMixer());
12	
13	    expect(result.current.gameState.currentMix).toEqual({ r: 0, g: 0, b: 0 }); // Starts from black
14	    expect(result.current.gameState.score).toBe(0);
15	    expect(result.current.gameState.completedChallenges).toBe(0);
16	    expect(result.current.gameState.challenge).toBeTruthy();
17	  });
18	
19	  test('addColor adds to the current color mix', () => {
20	    const { result } = renderHook(() => useColorMixer());
21	
22	    act(() => {
23	      result.current.addColor({ r: 50 });
24	    });
25	
26	    expect(result.current.gameState.currentMix.r).toBe(50); // 0 + 50
27	    expect(result.current.gameState.currentMix.g).toBe(0);
28	    expect(result.current.gameState.currentMix.b).toBe(0);
29	
30	    // Add more to test cumulative effect
31	    act(() => {
32	      result.current.addColor({ r: 30, g: 100 });
33	    });
34	
35	    expect(result.current.gameState.currentMix.r).toBe(80); // 50 + 30
36	    expect(result.current.gameState.currentMix.g).toBe(100); // 0 + 100
37	  });
38	
39	  test('addColor clamps upper values at 255', () => {
40	    const { result } = renderHook(() => useColorMixer());
41	
42	    // Add a lot of red to hit the upper limit
43	    act(() => {
44	      result.current.addColor({ r: 300 });
45	    });
46	    expect(result.current.gameState.currentMix.r).toBe(255);
47	
48	    // Test that it clamps at the upper bound
49	    act(() => {
50	      result.current.reset();
51	      result.current.addColor({ b: 100 });
52	      result.current.addColor({ b: 200 });
53	    });
54	    expect(result.current.gameState.currentMix.b).toBe(255); // 0 + 100 + 200 = 300, clamped to 255
55	  });
56	
57	  test('addColor clamps lower values at 0', () => {
58	    const { result } = renderHook(() => useColorMixer());
59	
60	    // Try to subtract from black
61	    act(() => {
62	      result.current.addColor({ r: -50 });
63	    });
64	    expect(result.current.gameState.currentMix.r).toBe(0); // Can't go below 0
65	
66	    // Add some color then subtract more than we have
67	    act(() => {
68	      result.current.addColor({ g: 50 });
69	      result.current.addColor({ g: -100 });
70	    });
71	    expect(result.current.gameState.currentMix.g).toBe(0); // 50 - 100 = -50, clamped to 0
72	  });
73	
74	  test('checkMatch correctly identifies close color matches', () => {
75	    const { result } = renderHook(() => useColorMixer());
