    history: [],
    future: [],
    elapsedMs: 0,
    status: 'in_progress',
    settings: defaultSettings(),
    version: 1,
  };
}

function defaultSettings(): Settings {
  return {
    validateOnInput: true,
    highlightPeers: true,
    highlightSameNumbers: true,
